        SELECT 1 FROM pg_constraint
        WHERE conrelid = rel AND contype IN ('p', 'u')
          AND conkey = ARRAY[(
              SELECT attnum FROM pg_attribute
              WHERE attrelid = rel AND attname = 'id'
                AND attnum > 0 AND NOT attisdropped
